        return false;
    }
    if (qstrncmp(tag, "gimp xcf", 8) != 0) {
//             qDebug() << "XCF: read called on non-XCF file";
        return false;
    }

    xcf_io >> xcf_image.width >> xcf_image.height >> xcf_image.type;

